"""1.6.0 (FW-0061): the portal interface contract 1. tests/fixtures/portal_contract_v1.json is generated by
portal.contract_text() from roles.py and portal.py, byte for byte, and its sha256 is pinned here (the HOM repo pins
the same value for its copy, fwportal/contract/v1.json): changing the contract means regenerating the fixture,
updating this constant, PORTAL_CONTRACT.md and HOM's copy together. 1.7.0 (Release C): contract 1 revision 2, tickets
on the portal (the same file name: fwp and contract stay 1). Synthetic data only."""
import hashlib
import json
import os
import re

import pytest

import portal as PT
import roles

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FIXTURE = os.path.join(HERE, "tests", "fixtures", "portal_contract_v1.json")
DOC = os.path.join(HERE, "PORTAL_CONTRACT.md")
CONTRACT_SHA256 = "c8d37db297553379ca4bf1676db2884dd9d61443690a9d3bdada867ddf9f0e0a"


def _fx():
    return json.load(open(FIXTURE, encoding="utf-8"))


def test_fixture_regenerates_byte_for_byte_and_is_pinned():
    raw = open(FIXTURE, "rb").read()
    assert PT.contract_text().encode("utf-8") == raw, "regenerate: python -c 'import portal; ...contract_text()'"
    assert hashlib.sha256(raw).hexdigest() == CONTRACT_SHA256
    assert raw.isascii() and chr(0x2014).encode("utf-8") not in raw


def test_lists_are_the_roles_tables():
    fx = _fx()
    assert fx["contract"] == fx["fwp"] == roles.CONTRACT == PT.FWP == 1
    assert fx["revision"] == roles.CONTRACT_REVISION == 2
    assert fx["commands"]["allowed"] == list(roles.PORTAL_CMDS)
    assert fx["commands"]["refused"] == list(roles.PORTAL_REFUSED)
    assert fx["prefs"] == json.loads(json.dumps(roles.PREF_KEYS)) and fx["file_kinds"] == roles.FILE_KINDS
    assert fx["events"]["fields"] == list(roles.EVENT_FIELDS)
    assert fx["events"]["kinds"] == list(roles.PORTAL_EVENTS) + list(roles.MACHINE_EVENTS) + list(roles.OWN_EVENTS)
    assert fx["commands"]["tickets"] == json.loads(json.dumps(roles.TICKET_CMDS))
    assert fx["commands"]["ticket_rules"] == list(roles.TICKET_RULES)
    assert fx["commands"]["pilot_ticket_actions"] == list(roles.PILOT_TICKET_ACTIONS) == ["verify", "reopen", "note"]
    assert fx["commands"]["pilot_ticket_limits"] == roles.PILOT_TICKET_LIMITS
    assert fx["tabs"] == list(roles.PORTAL_TABS) and fx["tabs"][-1] == "tickets"
    assert fx["caps"] == PT.CAPS and fx["uid"] == fx["gid"] == 2061
    assert fx["test_key"]["public_key"] == PT.public_id(PT.test_key())
    assert "not a real key" in fx["test_key"]["label"]


def test_every_subscription_is_allowed_or_refused_and_none_is_both():
    allowed, refused = set(roles.PORTAL_CMDS), set(roles.PORTAL_REFUSED)
    assert not allowed & refused
    assert set(roles.SUBS) == allowed | refused  # every MQTT command topic an instance takes is classified
    for s in allowed:
        assert roles.FEATURES[roles.SUBS[s]][1] is True, s  # offered on a portal
    for s in refused:
        f = roles.SUBS[s]
        assert f == roles.INTERNAL or roles.FEATURES[f][1] is False, s
    for f in ("value", "comm_why", "pay", "captain", "contact", "detail_url", "url", "picked_by", "emp", "name",
              "title", "narrative", "text", "reporter", "kind"):
        assert f not in roles.EVENT_FIELDS, f  # plan risk K1: pay and personal data never leave the instance
    assert {"comm", "month_rule"} <= set(roles.EVENT_FIELDS)


def test_signed_samples_verify_and_bad_ones_fail():
    fx = _fx()
    pub = fx["test_key"]["public_key"]
    for s in fx["samples"]["envelopes"]:
        kind = PT.kind_of(s["file"])
        assert kind and PT.verify(pub, s["envelope"], kind, "demo") == s["envelope"]["payload"]
        json.loads(s["envelope"]["payload"])
    for b in fx["samples"]["bad_envelopes"]:
        kind = PT.kind_of(b.get("file", "state.json"))
        with pytest.raises(PT.PortalError):
            PT.verify(pub, b["envelope"], kind, "demo", after=b.get("after"))
    ev = json.loads(fx["samples"]["envelopes"][2]["envelope"]["payload"])["events"][0]
    assert set(ev["data"]) <= set(roles.EVENT_FIELDS) and "Doe" not in json.dumps(ev)


def test_command_samples_match_the_spool(tmp_path):
    """Every sample through its own Spool (a new one each time: the 30-a-minute cap is not what a sample tests)."""
    fx = _fx()
    in_dir = tmp_path / "in"
    in_dir.mkdir()
    for s in fx["samples"]["commands"]["accepted"]:
        sp = PT.Spool("demo", now=lambda: 1763600000.5)
        (in_dir / s["name"]).write_text(json.dumps(s["cmd"]))
        cid, sub, payload = sp.take(str(in_dir / s["name"]))
        assert (cid, sub, payload) == (s["cmd"]["id"], s["cmd"]["sub"], s["cmd"]["payload"])
    for s in fx["samples"]["commands"]["refused"]:
        sp = PT.Spool("demo", now=lambda: 1763600000.5)
        (in_dir / s["name"]).write_text(json.dumps(s["cmd"]))
        with pytest.raises(PT.PortalError):
            sp.take(str(in_dir / s["name"]))
    assert os.listdir(in_dir) == []


def test_ticket_samples_match_check_ticket():
    """1.7.0: each ticket sample, accepted or refused, through check_ticket alone: the refused ones for the shape
    (the sub is allowed), so HOM's generic checkTicket must refuse each for the same rules."""
    fx = _fx()
    acc = [s for s in fx["samples"]["commands"]["accepted"] if s["cmd"]["sub"].startswith("ticket/")]
    ref = [s for s in fx["samples"]["commands"]["refused"] if s["cmd"]["sub"].startswith("ticket/")]
    assert {s["cmd"]["sub"] for s in acc} == {s["cmd"]["sub"] for s in ref} == set(roles.TICKET_CMDS)
    for s in acc:
        assert isinstance(PT.check_ticket(s["cmd"]["sub"], s["cmd"]["payload"]), dict), s
    for s in ref:
        with pytest.raises(PT.PortalError):
            PT.check_ticket(s["cmd"]["sub"], s["cmd"]["payload"])
    whys = {s["why"] for s in ref}
    for w in ("worker action fixed", "worker action triage", "worker action progress", "worker action close",
              "note with no text", "new with an inline image", "new names a reporter", "new with images 2.5",
              "image i over n", "image data is a data URL", "image data with a trailing newline", "id not FW-nnnn",
              "new title over 200 code points"):
        assert w in whys, w
    by = {json.loads(s["cmd"]["payload"]).get("title", "") for s in acc if s["cmd"]["sub"] == "ticket/new"}
    cap = [t for t in by if len(t) == 200]
    assert cap and any(ord(c) > 0xFFFF for c in cap[0])  # code points, not UTF-16 units (JS length would say 201)
    assert any('"images":2.0' in s["cmd"]["payload"] for s in acc)  # a whole float is a whole number (JS cannot tell)


OWN_FOLDER = ("finds", "school", "versions", "pickers", "recall", "pilotver", "tickets")  # pairings is shared


def _remap(url, pilot="demo"):
    """What the portal's shim does with a card's file URL (a reference for HOM's shim.test.mjs). 1.7.0: a kind kept
    in the pilot's own folder maps only from his folder (the admin's no-folder file and another pilot's give None)."""
    m = re.fullmatch(r"/local/flight-watcher/(?:([a-z0-9_]+)/)?([a-z]+)_([^?]+)\.json(?:\?.*)?", url)
    if not m:
        return None
    who, kind, rest = m.group(1), m.group(2), m.group(3)
    if kind not in roles.FILE_KINDS or (kind in OWN_FOLDER and who != pilot) or (kind not in OWN_FOLDER and who):
        return None
    pat = roles.FILE_KINDS[kind]
    if not pat:
        return f"/fw/api/file/{kind}", kind, ""
    arg = re.match(pat, rest).group(0)
    return f"/fw/api/file/{kind}/{arg}", kind, arg


def test_file_url_samples():
    fx = _fx()
    kinds = set()
    for s in fx["samples"]["file_urls"]:
        assert _remap(s["url"]) == (s["api"], s["kind"], s["arg"]), s
        kinds.add(s["kind"])
    assert kinds == set(roles.FILE_KINDS)
    assert fx["samples"]["file_urls_refused"]
    for s in fx["samples"]["file_urls_refused"]:  # 1.7.0: the admin's tickets list and another pilot's folder
        assert _remap(s["url"]) is None, s


def test_doc_names_everything_in_the_contract():
    doc = open(DOC, encoding="utf-8").read()
    assert chr(0x2014) not in doc
    assert "| contract 1 (`fwp` 1) | 1.6.0 | 1.6.0 |" in doc
    assert "| contract 1 rev 2 (`fwp` 1) | 1.7.0 | 1.8.0 | tickets on the portal |" in doc
    for s in roles.PORTAL_CMDS:
        assert f"`{s if s != 'rule/+/live/set' else 'rule/<id>/live/set'}`" in doc, s
    for s in roles.PORTAL_REFUSED:
        assert f"`{s}`" in doc, s
    for k in roles.PORTAL_EVENTS + roles.MACHINE_EVENTS + roles.OWN_EVENTS:
        assert f"`{k}`" in doc, k
    for f in roles.EVENT_FIELDS:
        assert re.search(r"\b%s\b" % f, doc), f
    for k in roles.FILE_KINDS:
        assert f"`{k}`" in doc, k
    for k in roles.PREF_KEYS:
        assert f"`{k}`" in doc, k
    for word in ("256 KB", "2 MB", "64 KB", "8 MB", "1 MB", "300 s", "600 s", "0640", "0750", "0700", "0755",
                 "2061", "portal signing key ed25519:", "fw_signing_key", "https://ntfy.sh/<topic>",
                 "portal_contract_v1.json", "fwportal/contract/v1.json",
                 # 1.7.0 (Release C)
                 "revision 2", "check_ticket", "checkTicket", "ticket_rules", "pilot_ticket_limits", "re-encode",
                 "60000", "1.5 MB", "untrusted", "tickets_fixed_seen.json", "priority 2"):
        assert word in doc, word
    for a in roles.PILOT_TICKET_ACTIONS:
        assert f"`{a}`" in doc, a
    # the two sentences 1.6.2 left behind (section 6 named only a token; 5.3 seeded prefs from the HA helpers)
    assert "topic only" in doc and "seeded once from the HA helpers" not in doc
